    -- settings of the hidden core menu itself: not ported into Noir
    local SKIP_FLAG = {
        ps_key = true, ps_blur = true, ps_op = true,
        ps_fscale = true, ps_scale = true, ps_acc = true,
    }

    local TAB_ICON = {
        aim = "crosshair", trigger = "zap", visuals = "eye", misc = "settings",
        skins = "shirt", settings = "settings", world = "globe", map = "map",
        bomb = "bomb", movement = "move", utility = "wrench",
        feedback = "message-circle", players = "users",
    }

    local window = Library:CreateWindow({
        Name            = "NOIR",
        Title           = "NOIR",
        LoadingTitle    = "NOIR",
        LoadingSubtitle = "NOIR CREATOR",
        ToggleUIKeybind = "RightControl",
        Theme           = "Noir",
        DefaultTheme    = "Noir",
        Weather         = "Rain",
        ConfigurationSaving = {
            Enabled    = true,
            FolderName = "NoirCreator",
        },
        ToggleButton = { Platform = "Both", Icon = "layout-grid" },
        Home = {
            Discord = "discord.gg/BksGHtSTh",
            DiscordTitle = "Discord",
        },
    })

    genv.NoirAutoUnload = function()
        pcall(function() window:Destroy() end)
        pcall(function()
            -- stop this run's extra-feature runtime (rebind-safe re-execute)
            xDTaraZ.State.Alive = false
            xDTaraZ.Combat.Unload()
            for _, c in ipairs(xDTaraZ.State.Connections) do
                pcall(function() c:Disconnect() end)
            end
        end)
    end

    -- ── load the embedded core logic ──────────────────────────────────────────
    local loadErr = nil
    do
        local okl, errl = pcall(function()
            local f, cerr = loadstring(CORE_SRC, "=noir_core")
            if not f then error("compile: " .. tostring(cerr), 0) end
            local okr, rerr = pcall(f)
            if not okr then error("run: " .. tostring(rerr), 0) end
        end)
        if not okl then loadErr = tostring(errl) end
    end

    -- the core publishes its app state through the injection inside module "e"
    local st = genv.NOIR_CORE
    if not st and not loadErr then
        for _ = 1, 200 do
            task.wait(0.05)
            st = genv.NOIR_CORE
            if st then break end
        end
    end
    if not loadErr and (type(st) ~= "table" or type(st.lib) ~= "table") then
        loadErr = "core did not publish its menu state"
    end

    if loadErr then
        -- graceful failure: Noir stays usable and explains what happened
        local tb = window:CreateTab({ Name = "Error", Icon = "triangle-alert" })
        local gb = tb:AddLeftGroupbox({ Name = "CORE" })
        gb:CreateParagraph({
            Title = "Failed to load core",
            Content = loadErr,
        })
        gb:CreateLabel("The embedded module did not start. Tell the build author and attach the error text from the console.")
        window:Toggle(true)
        warn("[Noir] core: " .. loadErr)
    else
        local okb, errb = pcall(function()

            local C = st.lib
            local els = C.els or {}

            -- hide the native core window right away
            pcall(function() C:toggle(false) end)
            -- block its window from ever showing again (Insert key etc.)
            pcall(function()
                local origToggle = C.toggle
                C.toggle = function(self, show)
                    if show == nil or show == true then return self end
                    return origToggle(self, show)
                end
            end)
            -- clear its own menu keybind so it never shows in bind lists
            pcall(function()
                local kb = C.fl and C.fl.ps_key
                if kb and type(kb.setkey) == "function" then kb:setkey(nil) end
            end)

            -- ── bridge state ──────────────────────────────────────────────────
            local records, byEl, dependents = {}, {}, {}

            local function eff(el)
                if type(el.eff) == "function" then
                    local okr, r = pcall(el.eff, el)
                    if okr then return r end
                end
                return el.val
            end

            local resyncAll
            local resyncQueued = false
            local function queueResync()
                if resyncQueued then return end
                resyncQueued = true
                task.delay(0.6, function()
                    resyncQueued = false
                    if genv.NoirCoreGen == gen then resyncAll() end
                end)
            end

            local function updateDeps(srcEl)
                local list = dependents[srcEl]
                if not list then return end
                for i = 1, #list do
                    local rec = list[i]
                    if rec.visFn and rec.ui and rec.ui.SetVisible then
                        pcall(rec.ui.SetVisible, rec.ui, rec.visFn())
                    end
                end
            end

            local function apply(el, fn)
                local okr, rerr = pcall(fn)
                if not okr then
                    warn("[Noir] set failed on '" .. tostring(el.name) .. "': " .. tostring(rerr))
                end
                updateDeps(el)
                queueResync()
            end

            -- ── read the core element tree ─────────────────────────────────
            local function rootOf(el)
                local c = el.c
                for _ = 1, 12 do
                    if not c or c.kind == nil then break end
                    c = c.c
                end
                return c
            end

            local function skipped(el)
                -- nested elements link to their parent through .host
                local p, n = el, 0
                while p and n < 12 do
                    if p.tmp or (p.o and p.o.tmp) then return true end
                    if p.flag and SKIP_FLAG[p.flag] then return true end
                    p = p.host
                    n = n + 1
                end
                return false
            end

            local tabList, tabSeen = {}, {}
            local pageOfTab, pageSeen = {}, {}
            local secOfPage, secSeen, secMeta = {}, {}, {}
            local itemsOfSec = {}

            for i = 1, #els do
                local el = els[i]
                if type(el) == "table" and type(el.o) == "table" and not skipped(el) then
                    local root = rootOf(el)
                    local tab = root and root.tab
                    if tab and type(tab.name) == "string" then
                        if not tabSeen[tab] then
                            tabSeen[tab] = true
                            tabList[#tabList + 1] = tab
                            pageOfTab[tab] = {}
                            pageSeen[tab] = {}
                        end
                        local page = root.page or tab
                        if not pageSeen[tab][page] then
                            pageSeen[tab][page] = true
                            pageOfTab[tab][#pageOfTab[tab] + 1] = page
                        end
                        local sec = root.sec or root
                        if not secSeen[page] then secSeen[page] = {} end
                        if not secSeen[page][sec] then
                            secSeen[page][sec] = true
                            secOfPage[page] = secOfPage[page] or {}
                            secOfPage[page][#secOfPage[page] + 1] = sec
                            local nm = ""
                            if root.sec and type(root.sec.name) == "string" then nm = root.sec.name end
                            secMeta[sec] = { name = nm, tab = tab, page = page }
                            itemsOfSec[sec] = {}
                        end
                        local arr = itemsOfSec[sec]
                        arr[#arr + 1] = el
                    end
                end
            end

            -- ── my own tab layout: tabs reshuffled, sections truly scattered ──
            local MY_TABS = {
                { name = "Combat",   icon = "crosshair", subs = { "General", "Extra" } },
                { name = "Misc",     icon = "wrench",    subs = { "General", "Extra" } },
                { name = "Visuals",  icon = "eye",       subs = { "General", "Extra" } },
                { name = "Settings", icon = "settings",  subs = nil },
            }
            local CONTENT = { 1, 2, 3 } -- MY_TABS indices that take scattered secs
            -- the Skins tab is NOT ported from the core: the real skin changer
            -- from the user's own build is appended as the last tab below

            local noirTabs = {}
            for mi = 1, #MY_TABS do
                local mine = MY_TABS[mi]
                local ntab = window:CreateTab({ Name = mine.name, Icon = mine.icon })
                noirTabs[mine.name] = ntab
                if mine.subs then
                    mine.tabs = {}
                    for sIdx = 1, #mine.subs do
                        mine.tabs[sIdx] = ntab:CreateSubTab({ Name = mine.subs[sIdx] })
                    end
                end
            end

            -- pool every section of every his tab; his settings stays whole,
            -- his skins port is dropped entirely (replaced by the real system)
            local pool, coreSecs = {}, {}
            for ti = 1, #tabList do
                local tab = tabList[ti]
                local ln = string.lower(tab.name)
                local isSet = ln == "settings"
                local isDrop = ln == "skins"
                for pi = 1, #pageOfTab[tab] do
                    local page = pageOfTab[tab][pi]
                    local secs = secOfPage[page]
                    if secs then
                        for si = 1, #secs do
                            local sec = secs[si]
                            if isSet then
                                coreSecs[#coreSecs + 1] = sec
                            elseif not isDrop then
                                pool[#pool + 1] = sec
                            end
                        end
                    end
                end
            end

            -- deal sections round-robin: consecutive secs land in different tabs,
            -- and inside each tab they alternate subtab and side
            local groupOfSec = {}
            for si = 1, #pool do
                local sec = pool[si]
                local mine = MY_TABS[CONTENT[(si - 1) % #CONTENT + 1]]
                local j = math.floor((si - 1) / #CONTENT)
                local host = mine.tabs[j % #mine.subs + 1]
                local meta = secMeta[sec]
                local nm = (meta.name ~= "" and meta.name) or "Settings"
                local gb
                if j % 2 == 0 then
                    gb = host:AddLeftGroupbox({ Name = nm })
                else
                    gb = host:AddRightGroupbox({ Name = nm })
                end
                groupOfSec[sec] = gb
            end

            -- his settings sections live straight on the Settings tab
            do
                local st = noirTabs["Settings"]
                for si = 1, #coreSecs do
                    local sec = coreSecs[si]
                    local meta = secMeta[sec]
                    local nm = (meta.name ~= "" and meta.name) or "Settings"
                    if si % 2 == 1 then
                        groupOfSec[sec] = st:AddLeftGroupbox({ Name = nm })
                    else
                        groupOfSec[sec] = st:AddRightGroupbox({ Name = nm })
                    end
                end
            end

            -- ── element mapping ───────────────────────────────────────────────
            local function nflag(el)
                if el.flag and el.flag ~= "" then return "sh_" .. el.flag end
                return nil
            end

            local function valNames(el)
                local disps, d2v, v2d = {}, {}, {}
                local src
                if el.kind == "crd" and type(el.items) == "table" then
                    src = el.items
                else
                    src = el.o.values or el.o.options
                end
                if type(src) == "table" then
                    for i = 1, #src do
                        local e = src[i]
                        local val, nm
                        if type(e) == "table" then
                            val = (e.value ~= nil and e.value) or (e.v ~= nil and e.v) or e.name or e
                            nm = tostring(e.name or e.n or val)
                        else
                            val = e
                            nm = tostring(e)
                        end
                        if v2d[val] == nil then
                            v2d[val] = nm
                            if d2v[nm] == nil then d2v[nm] = val end
                            disps[#disps + 1] = nm
                        end
                    end
                end
                return disps, d2v, v2d
            end

            local function addEl(gb, el)
                local kind = el.kind
                local name = tostring(el.name or "")
                local rec = { el = el, kind = kind }

                -- unnamed nested elements (e.g. a color under a toggle)
                if name == "" and kind ~= "btn" and kind ~= "lbl" and kind ~= "sub" then
                    local host = el.host
                    local hn = host and tostring(host.name or "") or ""
                    name = (hn ~= "" and (hn .. " · option")) or "Setting"
                end

                if kind == "tgl" then
                    rec.ui = gb:CreateToggle({
                        Name = name,
                        Default = eff(el) == true,
                        Flag = nflag(el),
                        Callback = function(v)
                            apply(el, function() el:set(v == true) end)
                        end,
                    })
                elseif kind == "sld" then
                    local mn = tonumber(el.min) or 0
                    local mx = tonumber(el.max) or 100
                    local stp = tonumber(el.step) or 1
                    rec.ui = gb:CreateSlider({
                        Name = name,
                        Min = mn, Max = mx,
                        Increment = stp,
                        Suffix = tostring(el.suf or ""),
                        Default = tonumber(eff(el)) or mn,
                        Flag = nflag(el),
                        Callback = function(v)
                            apply(el, function() el:set(tonumber(v) or v) end)
                        end,
                    })
                elseif kind == "drp" or kind == "crd" then
                    local disps, d2v, v2d = valNames(el)
                    local multi = (kind == "drp" and el.multi == true) or false
                    local cur = eff(el)
                    local def
                    if multi then
                        def = {}
                        if type(cur) == "table" then
                            for i = 1, #cur do
                                local d = v2d[cur[i]]
                                if d then def[#def + 1] = d end
                            end
                        end
                    else
                        def = v2d[cur]
                    end
                    rec.disp = { d2v = d2v, v2d = v2d, multi = multi }
                    rec.ui = gb:CreateDropdown({
                        Name = name,
                        Options = disps,
                        Default = def,
                        Multi = multi,
                        AllowNone = el.o.none == true,
                        Flag = nflag(el),
                        Callback = function(opt)
                            apply(el, function()
                                if multi then
                                    local vals = {}
                                    if type(opt) == "table" then
                                        for i = 1, #opt do
                                            local v = d2v[opt[i]]
                                            if v ~= nil then vals[#vals + 1] = v end
                                        end
                                    end
                                    el:set(vals)
                                else
                                    local v = d2v[opt]
                                    if v ~= nil then el:set(v) end
                                end
                            end)
                        end,
                    })
                elseif kind == "cpk" then
                    local cur = eff(el)
                    if typeof and typeof(cur) ~= "Color3" then cur = Color3.new(1, 1, 1) end
                    rec.ui = gb:CreateColorPicker({
                        Name = (name ~= "" and name) or "Color",
                        Default = cur,
                        Flag = nflag(el),
                        Callback = function(col)
                            apply(el, function() el:set(col) end)
                        end,
                    })
                elseif kind == "kbd" then
                    rec.ui = gb:CreateKeybind({
                        Name = name,
                        Default = el.val,
                        Flag = nflag(el),
                        Callback = function(key)
                            apply(el, function()
                                if typeof and typeof(key) == "EnumItem" then
                                    el:setkey(key)
                                elseif key == nil and el.o.nonone then
                                    el:setkey(nil)
                                end
                            end)
                        end,
                    })
                elseif kind == "inp" then
                    rec.ui = gb:CreateInput({
                        Name = name,
                        Default = tostring(eff(el) or ""),
                        Placeholder = tostring(el.o.placeholder or ""),
                        Flag = nflag(el),
                        Callback = function(text)
                            apply(el, function() el:set(tostring(text or "")) end)
                        end,
                    })
                elseif kind == "btn" then
                    local style
                    if el.o.style == "danger" then style = "Danger"
                    elseif el.o.style == "primary" then style = "Primary" end
                    rec.ui = gb:CreateButton({
                        Name = name,
                        Style = style,
                        Callback = function()
                            apply(el, function()
                                if type(el.press) == "function" then el:press() end
                            end)
                        end,
                    })
                elseif kind == "lbl" then
                    if name ~= "" then
                        rec.ui = gb:CreateLabel(name)
                    end
                elseif kind == "sub" then
                    if name ~= "" then
                        rec.ui = gb:CreateSection(name)
                    end
                end

                if rec.ui then
                    records[#records + 1] = rec
                    byEl[el] = rec
                end
            end

            for ti = 1, #tabList do
                local tab = tabList[ti]
                for pi = 1, #pageOfTab[tab] do
                    local page = pageOfTab[tab][pi]
                    local secs = secOfPage[page]
                    if secs then
                        for si = 1, #secs do
                            local sec = secs[si]
                            local gb = groupOfSec[sec]
                            local arr = itemsOfSec[sec]
                            if gb and arr then
                                for ii = 1, #arr do
                                    pcall(addEl, gb, arr[ii])
                                end
                            end
                        end
                    end
                end
            end

            -- ── dependencies (grayed/hidden elements in the core) ──────────────
            local function depPass(src, want)
                local v = eff(src)
                if type(want) == "function" then
                    local okr, r = pcall(want, v)
                    return okr and r == true
                elseif want == nil then
                    return v == true
                elseif type(v) == "table" then
                    for i = 1, #v do
                        if v[i] == want then return true end
                    end
                    return false
                end
                return v == want
            end

            for i = 1, #els do
                local el = els[i]
                if type(el) == "table" and type(el.deps) == "table" and #el.deps > 0 then
                    local rec = byEl[el]
                    if rec and rec.ui and rec.ui.SetVisible then
                        rec.visFn = function()
                            for d = 1, #el.deps do
                                local dep = el.deps[d]
                                if not depPass(dep.src, dep.want) then return false end
                            end
                            return el.dis ~= true
                        end
                        pcall(rec.ui.SetVisible, rec.ui, rec.visFn())
                        for d = 1, #el.deps do
                            local srcEl = el.deps[d].src
                            dependents[srcEl] = dependents[srcEl] or {}
                            local lst = dependents[srcEl]
                            local found = false
                            for k = 1, #lst do
                                if lst[k] == rec then found = true break end
                            end
                            if not found then lst[#lst + 1] = rec end
                        end
                    end
                end
            end

            -- ── periodic re-sync (config autoload, profiles, rounding) ────────
            resyncAll = function()
                for i = 1, #records do
                    local rec = records[i]
                    local ui = rec.ui
                    if ui and ui.Get and ui.Set then
                        pcall(function()
                            local el = rec.el
                            local v = eff(el)
                            if rec.kind == "tgl" then
                                if ui:Get() ~= (v == true) then ui:Set(v == true, true) end
                            elseif rec.kind == "sld" then
                                local num = tonumber(v)
                                if num and ui:Get() ~= num then ui:Set(num, true) end
                            elseif rec.kind == "drp" or rec.kind == "crd" then
                                local dd = rec.disp
                                if dd.multi then
                                    local want = {}
                                    if type(v) == "table" then
                                        for k = 1, #v do
                                            local d = dd.v2d[v[k]]
                                            if d then want[#want + 1] = d end
                                        end
                                    end
                                    local curv = ui:Get()
                                    local same = false
                                    if type(curv) == "table" and #curv == #want then
                                        same = true
                                        for k = 1, #want do
                                            if curv[k] ~= want[k] then same = false break end
                                        end
                                    end
                                    if not same then ui:Set(want, true) end
                                else
                                    local d = dd.v2d[v]
                                    if d and ui:Get() ~= d then ui:Set(d, true) end
                                end
                            elseif rec.kind == "cpk" then
                                if typeof and typeof(v) == "Color3" and ui:Get() ~= v then
                                    ui:Set(v, true)
                                end
                            elseif rec.kind == "kbd" then
                                local curv = ui:Get()
                                if v ~= nil then
                                    if curv ~= v and (type(curv) ~= "userdata" or curv.Name ~= v.Name) then
                                        ui:Set(v, true)
                                    end
                                end
                            elseif rec.kind == "inp" then
                                local s = tostring(v or "")
                                if ui:Get() ~= s then ui:Set(s, true) end
                            end
                            if rec.visFn and ui.SetVisible then
                                ui:SetVisible(rec.visFn())
                            end
                        end)
                    end
                end
            end

            task.delay(1.5, function()
                if genv.NoirCoreGen == gen then resyncAll() end
            end)
            task.delay(4, function()
                if genv.NoirCoreGen == gen then resyncAll() end
            end)
            task.spawn(function()
                while genv.NoirCoreGen == gen do
                    task.wait(10)
                    if genv.NoirCoreGen == gen then resyncAll() end
                end
            end)

            -- ── extra features from the user's own BloxStrike build ──────────
            -- each feature is isolated: one failing must not take the rest down
            local function extra(name, fn)
                xDTaraZ.Util.Try(name, fn)
            end
            extra("ui window", function()
                xDTaraZ.UI.Window = window
            end)
            extra("skins load", xDTaraZ.Skins.Load)
            -- full skin changer tab (creates its own tab, lands last)
            extra("skins tab", function()
                xDTaraZ.UI.BuildSkins(window)
            end)
            -- obsidian aimbot: subtab under Combat
            extra("obsidian aimbot", function()
                xDTaraZ.UI.BuildObsidianAimbot(
                    noirTabs["Combat"]:CreateSubTab({ Name = "Obsidian Aimbot" }))
            end)
            -- protection: subtab under Misc
            extra("protection", function()
                local protSub = noirTabs["Misc"]:CreateSubTab({ Name = "Protection" })
                local akg = protSub:AddRightGroupbox({ Name = "AntiKick", Icon = "shield" })
                xDTaraZ.UI.Feed(xDTaraZ.UI.Toggle(akg, "AntiKick.Enable", {
                    Name = "Block kicks",
                    Desc = "Blocks LOCAL Kick attempts (client-side checks). Server-side kicks cannot be blocked - they come over the network.",
                    Default = false,
                }), function(value) xDTaraZ.Guard.SetAntiKick(value == true) end)
                xDTaraZ.UI.Feed(xDTaraZ.UI.Toggle(akg, "AntiKick.BlockTp", {
                    Name = "Anti Rejoin (block server hop)",
                    Desc = "Blocks game-initiated TeleportService moves, so the game cannot throw you to another server. Our Rejoin / Server Hop buttons still work.",
                    Default = true,
                }), function(value) xDTaraZ.Guard.antiKick.blockTp = value == true end)
                local ugb = protSub:AddRightGroupbox({ Name = "Utility", Icon = "folder" })
                ugb:CreateButtonRow({
                    { Name = "Rejoin", Callback = xDTaraZ.UI.Detach(xDTaraZ.World.Rejoin) },
                    { Name = "Server Hop", Callback = xDTaraZ.UI.Detach(xDTaraZ.World.ServerHop) },
                })
            end)
            -- every widget whose idx is an Options key mirrors into Options
            extra("options bind", function()
                for key in pairs(xDTaraZ.Options) do
                    local w = xDTaraZ.UI.Widgets[key]
                    if w then xDTaraZ.Util.Try("bind " .. key, xDTaraZ.UI.Bind, w, key) end
                end
            end)
            -- keep the loops alive: obsidian step + fov circle + skin job
            extra("combat boot", function()
                xDTaraZ.Combat.Start()
                xDTaraZ.Scheduler.Every("Skin Changer", 0.15, xDTaraZ.Skins.Step,
                    { "SkinChanger" }, xDTaraZ.Skins.Step)
                xDTaraZ.Scheduler.Boot()
            end)

            -- menu settings (themes, background, scale) + config manager
            local setTab = noirTabs["Settings"]
            if setTab then
                pcall(function()
                    setTab:CreateConfigManager({ Name = "Noir configs", Side = "Left" })
                end)
                pcall(function()
                    setTab:ThemeManager({ Name = "Menu settings", Side = "Right" })
                end)
            end

            -- ── auto-save: every change persists to the "autosave" config ─────
            pcall(function()
                window:LoadConfig("autosave", true) -- restore last session
            end)
            do
                local saveTimer = 0
                local function saveSoon()
                    saveTimer = saveTimer + 1
                    local t = saveTimer
                    task.delay(1.2, function()
                        if t ~= saveTimer then return end
                        pcall(function()
                            window:SaveConfig("autosave")
                        end)
                    end)
                end
                local function wrap(el)
                    if type(el) == "table" and type(el.Set) == "function"
                        and el._noirAuto ~= true then
                        el._noirAuto = true
                        local orig = el.Set
                        el.Set = function(self, ...)
                            saveSoon()
                            return orig(self, ...)
                        end
                    end
                end
                for _, el in pairs(Library.Flags) do
                    pcall(wrap, el)
                end
                -- elements created later (dynamic lists) get wrapped too
                local origFC = window._flagCreated
                window._flagCreated = function(self, flag, el)
                    if origFC then origFC(self, flag, el) end
                    pcall(wrap, el)
                end

                -- restored flag values must flow into the extra-feature
                -- options: a silent Set skips element callbacks, so the
                -- widget layer is pushed by hand after the config load
                for idx, widget in pairs(xDTaraZ.UI.Widgets) do
                    if Library.Flags[idx] and widget.Element
                        and type(widget.Element.Get) == "function" then
                        local ok, v = pcall(widget.Element.Get, widget.Element)
                        if ok and v ~= nil then
                            pcall(function() widget:Dispatch(v) end)
                        end
                    end
                end
            end

            pcall(function()
                window:Notify({
                    Title = "NOIR",
                    Content = "Ported elements: " .. tostring(#records),
                    Type = "Success",
                    Duration = 4,
                })
            end)
        end)

        if not okb then
            warn("[Noir] build failed: " .. tostring(errb))
            pcall(function()
                window:Notify({
                    Title = "NOIR",
                    Content = "Build error: " .. tostring(errb),
                    Type = "Error",
                    Duration = 6,
                })
            end)
        end
        window:Toggle(true)
    end

    print("[Noir] core loaded. RightControl / on-screen button.")
end

return Library
